export const questions=[
 {key:'purpose',title:'Как вы будете жить в доме?',hint:'Начнём с вашего сценария.',options:[['live','Жить круглый год','Основной дом для себя и семьи'],['weekend','Приезжать за город','Выходные, отпуск и спокойные утра'],['rent','Сдавать в аренду','Гостевой дом или загородный бизнес']]},
 {key:'size',title:'Сколько пространства вам нужно?',hint:'Указываем площадь застройки. Полезная площадь есть на планировках.',options:[['small','До 40 м²','Компактное пространство для одного или двоих'],['medium','40–80 м²','Больше места для семьи и гостей'],['large','От 80 м²','Просторный дом с отдельными комнатами'],['any','Пока не знаю','Покажите разные варианты']]},
 {key:'rooms',title:'Сколько отдельных спален хотите?',hint:'Подбор предварительный: расположение комнат проверим вместе на плане.',options:[['0','Студия','Одно открытое пространство'],['1','Одна спальня','Отдельное место для отдыха'],['2','Две и больше','Для семьи и гостей'],['any','Пока не определились','Посмотрим подходящие планировки']]},
 {key:'style',title:'Какая архитектура вам ближе?',hint:'Можно выбрать характер дома или оставить оба варианта.',options:[['barn','Барн','Скатная крыша, выразительный силуэт'],['flat','Флэт','Плоская крыша, чистые линии'],['any','Нравятся оба','Выбираю по планировке']]},
 {key:'budget',title:'Какой бюджет на сам дом?',hint:'Фундамент, доставка и дополнительные опции рассчитываются отдельно.',options:[['3000000','До 3 млн ₽','Компактные модели'],['5000000','До 5 млн ₽','Больше вариантов для семьи'],['8000000','До 8 млн ₽','Просторные проекты'],['any','Бюджет пока открыт','Сначала хочу увидеть дома']]},
 {key:'land',title:'Участок уже есть?',hint:'Это поможет подготовиться к разговору о доставке и установке.',options:[['yes','Да, участок есть','Можно обсудить подъезд и фундамент'],['search','Ещё выбираю','Дом и участок подбираю вместе'],['later','Это планы на будущее','Изучаю возможности']]}
];
export function bedroomCount(m){const text=m.description.toLowerCase();return /три спальни|тремя спальнями/.test(text)?3:/двумя.*спальн|две спальни/.test(text)?2:/спальней|одной спальн/.test(text)?1:0}
export function recommend(models,a){const budget=a.budget==='any'?Infinity:Number(a.budget||Infinity);const fitsSize=m=>a.size==='any'||!a.size||a.size==='small'&&m.area<40||a.size==='medium'&&m.area>=40&&m.area<=80||a.size==='large'&&m.area>80;const fitsStyle=m=>a.style==='any'||!a.style||(m.id.startsWith('flat')?'flat':'barn')===a.style;const fitsRooms=m=>a.rooms==='any'||!a.rooms||a.rooms==='0'&&bedroomCount(m)===0||a.rooms==='1'&&bedroomCount(m)===1||a.rooms==='2'&&bedroomCount(m)>=2;return models.map(m=>({model:m,exact:fitsSize(m)&&fitsStyle(m)&&fitsRooms(m)&&m.price<=budget,score:(fitsSize(m)?8:0)+(fitsStyle(m)?6:0)+(fitsRooms(m)?4:0)+(m.price<=budget?10:-Math.min(12,(m.price-budget)/500000))+(a.purpose==='rent'&&m.area<40?2:0)})).sort((a,b)=>b.score-a.score||a.model.price-b.model.price).slice(0,3)}
export function mountQuiz(container,models,{onDetail}={}){let step=0,answers={},results=false;const fmt=n=>new Intl.NumberFormat('ru-RU').format(n);function brief(){return 'Подбор дома DUROV.HOUSE\n'+questions.map(q=>q.title+' '+q.options.find(o=>o[0]===answers[q.key])?.[1]).join('\n')+'\nПодходящие проекты: '+recommend(models,answers).map(r=>r.model.name).join(', ')}function render(){if(results){const matches=recommend(models,answers),exact=matches.some(r=>r.exact);container.innerHTML=`<div class="quiz-progress"><span>ВАШ РЕЗУЛЬТАТ</span><span>6 / 6</span></div><h3 tabindex="-1">${exact?'Эти дома ближе к вашим пожеланиям.':'Посмотрите ближайшие варианты.'}</h3><p class="quiz-hint">${exact?'Начните с планировки — она расскажет больше площади.':'Все условия одновременно не совпали. Мы подобрали три ближайших проекта; бюджет и планировку можно обсудить индивидуально.'}</p><div class="quiz-results">${matches.map(({model:m,exact})=>`<button class="quiz-result" data-result="${m.id}"><img src="${m.image}" alt="${m.name}"><span><small>${exact?'ПО ПАРАМЕТРАМ':'БЛИЖАЙШИЙ ВАРИАНТ'}</small><strong>${m.name}</strong><span>${String(m.area).replace('.',',')} м² · ${fmt(m.price)} ₽</span><em>Посмотреть планировку ↗</em></span></button>`).join('')}</div><p class="footnote">Подбор предварительный. Количество спален зависит от планировки; точную комплектацию и стоимость подтвердит команда.</p><div class="quiz-actions"><button class="button outline" id="quiz-back">Изменить ответы</button><a class="button" id="quiz-email" href="mailto:sales@durov.house?subject=${encodeURIComponent('Подбор дома')}&body=${encodeURIComponent(brief())}">Обсудить подбор по почте ↗</a></div><button class="quiz-restart" id="quiz-restart">Пройти заново</button>`;container.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>onDetail?.(b.dataset.result));container.querySelector('#quiz-back').onclick=()=>{results=false;render()};container.querySelector('#quiz-restart').onclick=()=>{answers={};step=0;results=false;render()};return}const q=questions[step];container.innerHTML=`<div class="quiz-progress"><span>ШАГ ${step+1} ИЗ ${questions.length}</span><span>${Math.round(step/questions.length*100)}%</span></div><div class="quiz-meter"><span style="width:${step/questions.length*100}%"></span></div><h3 tabindex="-1">${q.title}</h3><p class="quiz-hint">${q.hint}</p><div class="quiz-options" role="group" aria-label="${q.title}">${q.options.map(([value,label,hint])=>`<button class="quiz-option ${answers[q.key]===value?'chosen':''}" data-answer="${value}" aria-pressed="${answers[q.key]===value}"><span class="quiz-check"></span><strong>${label}</strong><small>${hint}</small></button>`).join('')}</div><div class="quiz-actions"><button class="button outline" id="quiz-back" ${step===0?'disabled':''}>← Назад</button><span class="quiz-hint">Займёт около минуты</span><button class="button" id="quiz-next" ${!answers[q.key]?'disabled':''}>${step===questions.length-1?'Показать дома':'Дальше'} →</button></div>`;container.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[q.key]=b.dataset.answer;container.querySelectorAll('[data-answer]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))});container.querySelector('#quiz-next').disabled=false});container.querySelector('#quiz-back').onclick=()=>{step--;render();container.querySelector('h3')?.focus()};container.querySelector('#quiz-next').onclick=()=>{if(!answers[q.key])return;if(step===questions.length-1)results=true;else step++;render();container.querySelector('h3')?.focus()}}render();return{reset(){step=0;answers={};results=false;render()}}}
